function spawnHit(x,y,color){for(let i=0;i<9;i++)particles.push({x,y,vx:(Math.random()-.5)*7,vy:(Math.random()-.7)*7,life:18+Math.random()*10,size:2+Math.random()*3,color});}
function act(type){if(!running||paused||finished||!player)return;if(type==='e'){if(matchType!=='hardcore'){toast('Weapons are unlocked in HARDCORE rules!');return}if(!weapon){weapon={x:canvas.clientWidth*.52,y:canvas.clientHeight*.78};toast('Steel chair at ringside — bring it in!')}else{weapon=null;toast('Weapon dropped ringside.')}return}if(type==='m'){if(Math.abs(player.x-enemy.x)<64&&enemy.hp<24){finishMatch(true,'PIN! ONE, TWO, THREE!');return}toast('Get your rival down and weakened to go for the pin!');return}if(type===' '){if(player.st<=8){toast('Catch your breath first!');return}player.dodge=.32;player.st-=8;player.vx-=player.face*5;player.hype=Math.min(100,player.hype+4);return}let range=type==='k'?72:65;player.face=enemy.x>player.x?1:-1;player.attack=.25;player.st=Math.max(0,player.st-(type==='l'?24:type==='k'?12:7));if(type==='l'&&player.hype<50){toast('Build hype to 50% to hit your finisher!');return}if(type==='l')player.hype=0;let hit=Math.abs(player.x-enemy.x)<range&&Math.abs(player.y-enemy.y)<45;if(hit){let dmg=(type==='j'?6:type==='k'?12:24)*player.power;if(weapon)dmg*=1.6;enemy.hp=Math.max(0,enemy.hp-dmg);enemy.stun=type==='l'?.75:.32;enemy.down=type==='l'?.9:type==='k'?.45:0;player.hype=Math.min(100,player.hype+(type==='l'?14:12)+(manager==='moxie'?6:0));score+=type==='l'?300:type==='k'?120:60;enemy.vx=player.face*(type==='l'?9:4);enemy.vy=type==='l'?-6:type==='k'?-3:-1;enemy.flash=.16;spawnHit(enemy.x,enemy.y-35,type==='l'?'#d8ff3e':'#ffb25d');if(type==='l')showMessage('SIGNATURE MOVE!');else if(weapon)showMessage('CHAIR SHOT!');if(enemy.hp<=0)finishMatch(true,'KNOCKOUT! MAIN EVENT WON!')}else{player.vx=player.face*1.6;showMessage(type==='l'?'FINISHER MISSED!':'OUT OF RANGE!')}}
function showMessage(text){let el=$('#matchMsg');el.textContent=text;el.classList.add('visible');messageUntil=performance.now()+800}
function updateHud(){if(!player||!enemy)return;$('#playerHealth').style.width=player.hp+'%';$('#enemyHealth').style.width=enemy.hp+'%';$('#playerStamina').style.width=player.st+'%';$('#enemyStamina').style.width=enemy.st+'%';$('#hypeValue').textContent=Math.round(player.hype);let duration=matchType==='ironman'?180:120;let sec=Math.max(0,Math.floor(duration-elapsed));$('#timer').textContent=Math.floor(sec/60)+':'+String(sec%60).padStart(2,'0')}
function finishMatch(win,text){finished=true;running=false;score+=win?500:0;showMessage(text);$('#statusText').textContent=win?'MAIN EVENT: VICTORY':'MAIN EVENT: DEFEAT';$('#banner').textContent=win?'YOU JUST MADE THE MAIN EVENT.':'THE BELL WILL RING AGAIN.';toast(win?'Victory! '+score+' crowd points earned.':'Tough loss. Run it back!')}
function update(dt){let w=canvas.clientWidth,h=canvas.clientHeight;let move=0,vert=0;if(keys.a||keys.arrowleft)move--;if(keys.d||keys.arrowright)move++;if(keys.w||keys.arrowup)vert--;if(keys.s||keys.arrowdown)vert++;let sp=player.speed*(player.st<10?.65:1);player.vx+=move*sp*dt*14;player.vy+=vert*sp*dt*14;player.vx*=Math.pow(.06,dt);player.vy*=Math.pow(.06,dt);player.x+=player.vx;player.y+=player.vy;player.x=Math.max(w*.15,Math.min(w*.85,player.x));player.y=Math.max(h*.55,Math.min(h*.84,player.y));player.st=Math.min(100,player.st+(manager==='coach'?15:9)*dt);player.attack=Math.max(0,player.attack-dt);player.stun=Math.max(0,player.stun-dt);player.dodge=Math.max(0,player.dodge-dt);player.flash=Math.max(0,player.flash-dt);
let dx=player.x-enemy.x,dy=player.y-enemy.y,dist=Math.hypot(dx,dy);enemy.face=dx>0?1:-1;if(enemy.down>0){enemy.down-=dt;enemy.st=Math.min(100,enemy.st+8*dt)}else if(enemy.stun>0){enemy.stun-=dt}else{if(dist>52){enemy.vx+=Math.sign(dx)*enemy.speed*dt*9;enemy.vy+=Math.sign(dy)*enemy.speed*dt*7}else if(Math.random()<dt*.75){enemy.attack=.25;let dodged=player.dodge>0;let dmg=dodged?0:(6+Math.random()*5)*enemy.power*(matchType==='hardcore'&&weapon?.x<canvas.clientWidth*.5?1.35:1);if(dmg){player.hp=Math.max(0,player.hp-dmg);player.hype=Math.min(100,player.hype+8);player.stun=.16;player.vx+=Math.sign(dx)*3;spawnHit(player.x,player.y-34,'#ff596b')}if(player.hp<=0)finishMatch(false,'KNOCKOUT! RIVAL TAKES IT!')}enemy.vx*=Math.pow(.05,dt);enemy.vy*=Math.pow(.05,dt);enemy.x+=enemy.vx;enemy.y+=enemy.vy;enemy.x=Math.max(w*.15,Math.min(w*.85,enemy.x));enemy.y=Math.max(h*.55,Math.min(h*.84,enemy.y));enemy.st=Math.min(100,enemy.st+8*dt)}enemy.attack=Math.max(0,enemy.attack-dt);enemy.flash=Math.max(0,enemy.flash-dt);for(let p of particles){p.x+=p.vx;p.y+=p.vy;p.vy+=.12;p.life-=1}particles=particles.filter(p=>p.life>0);elapsed+=dt;if(matchType==='ironman'&&elapsed>=180)finishMatch(player.hp>=enemy.hp,'TIME! '+(player.hp>=enemy.hp?'POINTS VICTORY!':'RIVAL WINS ON POINTS!'));if(matchType!=='ironman'&&elapsed>=120)finishMatch(player.hp>=enemy.hp,'TIME! '+(player.hp>=enemy.hp?'JUDGES AWARD YOU THE WIN!':'RIVAL WINS ON POINTS!'));updateHud()}
function loop(t){if(!running||paused)return;let dt=Math.min(.04,(t-last)/1000||.016);last=t;update(dt);draw();if(messageUntil&&performance.now()>messageUntil){$('#matchMsg').classList.remove('visible');messageUntil=0}if(running)requestAnimationFrame(loop)}
const keyMap={j:'j',k:'k',l:'l',e:'e',m:'m',' ':' ',shift:' '};window.addEventListener('keydown',e=>{let k=e.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();keys[k]=true;if(keyMap[k]&&!e.repeat)act(keyMap[k]);if(k==='p'&&running&&!finished){paused=!paused;if(paused){$('#statusText').textContent='PAUSED · CATCH YOUR BREATH';showMessage('PAUSED');draw()}else{$('#statusText').textContent='LIVE FROM '+arena.toUpperCase();last=performance.now();requestAnimationFrame(loop)}}});window.addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
$$('.touch-btn[data-key]').forEach(b=>{let k=b.dataset.key;const on=e=>{e.preventDefault();keys[k]=true;if(['j','k','l','e'].includes(k))act(k)};const off=e=>{e.preventDefault();keys[k]=false};b.addEventListener('pointerdown',on);b.addEventListener('pointerup',off);b.addEventListener('pointercancel',off);b.addEventListener('pointerleave',off)});
// Initial static illustrated ring.
canvasSize();draw();
</script></body></html>

