Index: index.html
===================================================================
--- index.html
+++ index.html
@@ -14,5 +14,23 @@
 <section class="card"><div class="card-head"><div class="card-title">03 / YOUR CORNER</div><div class="step">MANAGER</div></div><div class="manager-row"><div class="manager-copy"><strong>Corner support</strong><small id="managerDesc">A little extra stamina regen</small></div><select class="select" id="managerSelect"><option value="none">No manager</option><option value="moxie">Moxie Vale</option><option value="coach">Coach Kaito</option><option value="dj">DJ Thunder</option></select></div></section>
 <section class="card"><div class="card-head"><div class="card-title">04 / THE LOCKER</div><div class="step">CUSTOM ATTIRE</div></div><div class="gear-row" id="gearChoices"></div><div class="gear-note" id="gearNote">Choose a colorway for your entrance gear.</div><div style="display:flex;justify-content:space-between;align-items:center;margin-top:8px"><label style="font-size:10px;color:#c1bec9"><input type="checkbox" id="altGear" style="accent-color:#d8ff3e;vertical-align:middle"> &nbsp;Use alternate trim</label><button class="download" id="downloadGear">↓ DOWNLOAD GEAR</button></div></section></aside></main>
 <div class="bottomline"><span class="banner" id="banner">YOUR MOMENT IS NOW.</span><span>ORIGINAL CHARACTERS · ARCADE ACTION · PLAY FAIR</span></div><footer class="footer"><span><b>JWW</b> — JUST WIN WRESTLING</span><span>FICTIONAL ROSTER · STYLIZED ACTION · MADE FOR THE LOVE OF THE BELL</span></footer></div><div class="toast" id="toast"></div>
 <script>
+const rosterData=[{name:'The Phoenix',style:'High flyer',initials:'PX',c1:'#ff754d',c2:'#ffce42',speed:3.35,power:1},{name:'Iron Saint',style:'Powerhouse',initials:'IS',c1:'#597aff',c2:'#9ab9ff',speed:2.45,power:1.45},{name:'Nova Riot',style:'Technician',initials:'NR',c1:'#de4dff',c2:'#51e8ce',speed:3.1,power:1.13},{name:'Mack Steel',style:'Brawler',initials:'MS',c1:'#f84656',c2:'#942b4c',speed:2.7,power:1.35},{name:'Kaito Zero',style:'Submission ace',initials:'KZ',c1:'#31c7a2',c2:'#a7f458',speed:3.05,power:1.12},{name:'Duchess Vex',style:'Showstopper',initials:'DV',c1:'#d59aff',c2:'#7541de',speed:3.15,power:1.15}];
+const gears=[{name:'Voltage',color:'#d8ff3e'},{name:'Afterburn',color:'#ff596b'},{name:'Nightfall',color:'#8c75ff'},{name:'Deep Blue',color:'#39caff'},{name:'Gold Rush',color:'#ffbd4a'}];
+const arenaNames={warehouse:'THE WAREHOUSE · NORTH AMERICA',rooftop:'ROOFTOP RIOT · NEON DISTRICT',dojo:'IRON DOJO · OSAKA, JAPAN'};
+let selected=0,gear=0,matchType='singles',arena='warehouse',running=false,paused=false,finished=false,last=0,elapsed=0,keys={},player,enemy,weapon=null,particles=[],messageUntil=0,manager='none',score=0;
+const canvas=document.querySelector('#gameCanvas'),ctx=canvas.getContext('2d');const $=s=>document.querySelector(s),$$=s=>document.querySelectorAll(s);
+function roster(){ $('#roster').innerHTML=rosterData.map((r,i)=>`<button class="fighter ${selected===i?'active':''}" data-id="${i}"><div class="portrait" style="--c1:${r.c1};--c2:${r.c2}">${r.initials}</div><div class="fighter-name">${r.name}</div><div class="fighter-style">${r.style}</div></button>`).join('');$$('.fighter').forEach(b=>b.onclick=()=>{selected=+b.dataset.id;roster();draw()}) }
+function drawGears(){$('#gearChoices').innerHTML=gears.map((g,i)=>`<button title="${g.name}" aria-label="${g.name}" class="swatch ${gear===i?'active':''}" style="--sw:${g.color}" data-gear="${i}"></button>`).join('');$$('.swatch').forEach(b=>b.onclick=()=>{gear=+b.dataset.gear;drawGears();draw()})}
+roster();drawGears();
+function canvasSize(){let r=canvas.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,2);canvas.width=Math.max(1,Math.round(r.width*d));canvas.height=Math.max(1,Math.round(r.height*d));ctx.setTransform(d,0,0,d,0,0);draw()}
+window.addEventListener('resize',canvasSize);new ResizeObserver(canvasSize).observe(canvas);
+function fighterState(index,x,y){return {x,y,vx:0,vy:0,hp:100,st:100,hype:0,face:1,attack:0,stun:0,dodge:0,flash:0,down:0,score:0,...rosterData[index]}}
+function startGame(){player=fighterState(selected,canvas.clientWidth*.34,canvas.clientHeight*.65);let ei=(selected+1+Math.floor(Math.random()*5))%rosterData.length;enemy=fighterState(ei,canvas.clientWidth*.66,canvas.clientHeight*.65);player.gear=gears[gear].color;enemy.gear=rosterData[(ei+2)%rosterData.length].c1;weapon=null;particles=[];elapsed=0;score=0;running=true;paused=false;finished=false;$('#overlay').classList.add('hidden');$('#hud').classList.add('show');$('#playerHudName').textContent=player.name;$('#enemyHudName').textContent=enemy.name;$('#roundLabel').textContent='JWW · '+matchType.toUpperCase();$('#statusText').textContent='LIVE FROM '+arena.toUpperCase();$('#matchMsg').classList.remove('visible');$('#startBtn').textContent='REMATCH ↗';updateHud();draw();last=performance.now();requestAnimationFrame(loop);$('#banner').textContent='MAKE SOME NOISE.'}
+$('#startBtn').onclick=()=>{if(running&&paused){paused=false;$('#statusText').textContent='LIVE FROM '+arena.toUpperCase();last=performance.now();requestAnimationFrame(loop)}else startGame()};
+$$('#matchChoices .choice').forEach(b=>b.onclick=()=>{$$('#matchChoices .choice').forEach(x=>x.classList.remove('active'));b.classList.add('active');matchType=b.dataset.match;$('#roundLabel').textContent='JWW · '+matchType.toUpperCase();$('#introSub').textContent=matchType==='hardcore'?'ANYTHING GOES. KEEP IT CLEAN.':matchType==='ironman'?'THREE MINUTES. MOST FALLS WINS.':'ONE RING. NO EXCUSES.';draw()});
+$$('#arenaChoices .choice').forEach(b=>b.onclick=()=>{$$('#arenaChoices .choice').forEach(x=>x.classList.remove('active'));b.classList.add('active');arena=b.dataset.arena;$('#arenaLabel').textContent=arenaNames[arena];draw()});
+$('#managerSelect').onchange=e=>{manager=e.target.value;$('#managerDesc').textContent=manager==='none'?'A little extra stamina regen':manager==='moxie'?'Moxie boosts your hype on clean hits':manager==='coach'?'Coach Kaito keeps stamina topped up':'DJ Thunder powers up your finisher';toast(manager==='none'?'Corner is empty':`${e.target.options[e.target.selectedIndex].text} is in your corner!`)};
+function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),2100)}
+$('#downloadGear').onclick=downloadGear;$('#altGear').onchange=draw;

