function act(type){if(!running||paused||finished||!player)return;if(type==='e'){if(matchType!=='hardcore'){toast('Weapons are unlocked in HARDCORE rules!');return}if(!weapon){weapon={x:canvas.clientWidth*.52,y:canvas.clientHeight*.78};toast('Steel chair at ringside — bring it in!')}else{weapon=null;toast('Weapon dropped ringside.')}return}if(type==='m'){if(Math.abs(player.x-enemy.x)<64&&enemy.hp<24){finishMatch(true,'PIN! ONE, TWO, THREE!');return}toast('Get your rival down and weakened to go for the pin!');return}if(type===' '){if(player.st<=8){toast('Catch your breath first!');return}player.dodge=.32;player.st-=8;player.vx-=player.face*5;player.hype=Math.min(100,player.hype+4);return}let range=type==='k'?72:65;player.face=enemy.x>player.x?1:-1;player.attack=.25;player.st=Math.max(0,player.st-(type==='l'?24:type==='k'?12:7));if(type==='l'&&player.hype<50){toast('Build hype to 50% to hit your finisher!');return}if(type==='l')player.hype=0;let hit=Math.abs(player.x-enemy.x)<range&&Math.abs(player.y-enemy.y)<45;if(hit){let dmg=(type==='j'?6:type==='k'?12:24)*player.power;if(weapon)dmg*=1.6;if(manager==='dj'&&type==='l')dmg*=1.2;enemy.hp=Math.max(0,enemy.hp-dmg);enemy.stun=type==='l'?.75:.32;enemy.down=type==='l'?.9:type==='k'?.45:0;player.hype=Math.min(100,player.hype+(type==='l'?14:12)+(manager==='moxie'?6:0));score+=type==='l'?300:type==='k'?120:60;enemy.vx=player.face*(type==='l'?9:4);enemy.vy=type==='l'?-6:type==='k'?-3:-1;enemy.flash=.16;spawnHit(enemy.x,enemy.y-35,type==='l'?'#d8ff3e':'#ffb25d');if(type==='l')showMessage('SIGNATURE MOVE!');else if(weapon)showMessage('CHAIR SHOT!');if(enemy.hp<=0)finishMatch(true,'KNOCKOUT! MAIN EVENT WON!')}else{player.vx=player.face*1.6;showMessage(type==='l'?'FINISHER MISSED!':'OUT OF RANGE!')}}
