node - <<'JS'
const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async()=>{
 const browser=await chromium.launch({headless:true,executablePath:'/usr/bin/chromium',args:['--no-sandbox']});
 const errors=[],bad=[];
 const page=await browser.newPage({viewport:{width:1280,height:900},deviceScaleFactor:1});
 page.on('pageerror',e=>errors.push(e.message));page.on('console',m=>{if(m.type()==='error')errors.push(m.text())});page.on('response',r=>{if(r.status()>=400)bad.push(`${r.status()} ${r.url()}`)});
 await page.goto('http://localhost:3000',{waitUntil:'networkidle'});
 await page.screenshot({path:'/tmp/opencode/jww-setup.jpg',type:'jpeg',quality:68,fullPage:true});
 const [download]=await Promise.all([page.waitForEvent('download'),page.locator('#downloadGear').click()]);
 console.log('gear download:',download.suggestedFilename());
 await page.locator('#startBtn').click();await page.keyboard.press('p');
 console.log('pause:',await page.locator('#statusText').innerText());await page.keyboard.press('p');
 await page.screenshot({path:'/tmp/opencode/jww-match.jpg',type:'jpeg',quality:68});
 await page.setViewportSize({width:390,height:844});await page.reload({waitUntil:'networkidle'});
 console.log('mobile viewport:',await page.locator('.touch-controls').evaluate(el=>getComputedStyle(el).display),'horizontal overflow:',await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth));
 await page.locator('#startBtn').click();await page.locator('[data-key="j"]').dispatchEvent('pointerdown',{pointerId:1,pointerType:'touch',isPrimary:true});
 console.log('mobile started:',await page.locator('#statusText').innerText());
 await page.screenshot({path:'/tmp/opencode/jww-mobile.jpg',type:'jpeg',quality:68});
 console.log('console errors:',errors,'bad responses:',bad);
 await browser.close();
})().catch(e=>{console.error(e);process.exit(1)});
