node - <<'JS'
const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async()=>{
 const browser=await chromium.launch({headless:true,executablePath:'/usr/bin/chromium',args:['--no-sandbox']});
 const errors=[],bad=[];
 const page=await browser.newPage({viewport:{width:1280,height:900},deviceScaleFactor:1});
 page.on('pageerror',e=>errors.push(e.message));page.on('console',m=>{if(m.type()==='error')errors.push(m.text())});page.on('response',r=>{if(r.status()>=400)bad.push(`${r.status()} ${r.url()}`)});
 await page.goto('http://localhost:3000',{waitUntil:'networkidle'});
 await page.screenshot({path:'/tmp/opencode/jww-setup.jpg',type:'jpeg',quality:68,fullPage:true});
 await page.locator('[data-match="hardcore"]').click();
 await page.locator('[data-id="2"]').click();
 await page.locator('#startBtn').click();
 await page.keyboard.press('e');
 const start={status:await page.locator('#statusText').innerText(),match:await page.locator('#roundLabel').innerText(),weapon:await page.locator('#toast').innerText()};
 await page.keyboard.press('p');const paused=await page.locator('#statusText').innerText();await page.keyboard.press('p');
 await page.screenshot({path:'/tmp/opencode/jww-match.jpg',type:'jpeg',quality:68});
 await page.setViewportSize({width:390,height:844});await page.reload({waitUntil:'networkidle'});
 const mobile=await page.evaluate(()=>({width:innerWidth,scrollWidth:document.documentElement.scrollWidth,touchControls:getComputedStyle(document.querySelector('.touch-controls')).display}));
 await page.screenshot({path:'/tmp/opencode/jww-mobile.jpg',type:'jpeg',quality:68,fullPage:true});
 console.log(JSON.stringify({start,paused,mobile,errors,bad},null,2));
 await browser.close();
})().catch(e=>{console.error(e);process.exit(1)});
